#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int a[100005];
static int idx[100005];
static char on[100005];
static int n;

static int cmp(const void *x, const void *y) {
    long long va = a[*(const int*)x];
    long long vb = a[*(const int*)y];
    if (vb < va) return -1;
    if (vb > va) return 1;
    return 0;
}

int main(void) {
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);

    for (int i = 0; i < n; i++) idx[i] = i;
    qsort(idx, n, sizeof(int), cmp);

    /* Um corte na altura h produz: 1 pedaco (a base, sempre conectada)
       + o numero de blocos maximos consecutivos com Ai > h.
       Varremos os valores distintos em ordem decrescente, ativando os
       indices e contando componentes conectadas (blocos).          */
    long long best = 2; /* sempre possivel: corte abaixo de todas as alturas -> 2 pedacos */
    memset(on, 0, sizeof(on));
    int active = 0;
    int i = 0;
    while (i < n) {
        int v = a[idx[i]];
        while (i < n && a[idx[i]] == v) {
            int j = idx[i];
            int c = 1;
            if (j > 0 && on[j - 1]) c--;
            if (j + 1 < n && on[j + 1]) c--;
            active += c;
            on[j] = 1;
            i++;
        }
        if (active + 1 > best) best = active + 1;
    }
    printf("%lld\n", best);
    return 0;
}
